mapper.select:
SELECT contentid, contenttypeid, title, tel, addr1, addr2, lDongRegnCd, lDongSignguCd, mapx, mapy, firstimage, firstimage2, view_count AS viewCount FROM destination WHERE lDongRegnCd = #{lDongRegnCd}
AND lDongSignguCd = #{lDongSignguCd}
ORDER BY modifiedtime DESC

SELECT * FROM (
    SELECT 
        d.*,
        ROWNUM AS rn
    FROM (
        SELECT 
            contentid, contenttypeid, title, overview, homepage, tel,
            addr1, addr2, zipcode, lDongRegnCd, lDongSignguCd,
            mapx, mapy, mlevel, firstimage, firstimage2, modifiedtime,
            view_count AS viewCount, sync_date AS syncDate, created_at AS createdAt
        FROM destination
        WHERE contenttypeid = #{contenttypeid}
        AND lDongRegnCd = #{lDongRegnCd}

            AND lDongSignguCd = #{lDongSignguCd}

        ORDER BY contentid DESC
    ) d
    WHERE ROWNUM <= #{offset} + #{limit}
)
WHERE rn > #{offset}

SELECT SIGNGU_NAME 
FROM ldong_signgu_code 
WHERE LDONGREGNCD = #{lDongRegnCd} AND LDONGSIGNGUCD = #{lDongSignguCd}

SELECT COUNT(*) FROM destination
WHERE contenttypeid = #{contenttypeid}
AND lDongRegnCd = #{lDongRegnCd}

    AND lDongSignguCd = #{lDongSignguCd}

SELECT * FROM (
    SELECT 
        d.*,
        ROWNUM AS rn
    FROM (
        SELECT 
            contentid, contenttypeid, title, overview, homepage, tel,
            addr1, addr2, zipcode, lDongRegnCd, lDongSignguCd,
            mapx, mapy, mlevel, firstimage, firstimage2, modifiedtime,
            view_count AS viewCount, sync_date AS syncDate, created_at AS createdAt
        FROM destination
        WHERE (title LIKE '%' || #{keyword} || '%' OR addr1 LIKE '%' || #{keyword} || '%')
        AND lDongRegnCd = #{lDongRegnCd}

            AND lDongSignguCd = #{lDongSignguCd}

        ORDER BY view_count DESC, title ASC
    ) d
    WHERE ROWNUM <= #{offset} + #{limit}
)
WHERE rn > #{offset}

SELECT COUNT(*) FROM destination
WHERE (title LIKE '%' || #{keyword} || '%' OR addr1 LIKE '%' || #{keyword} || '%')
AND lDongRegnCd = #{lDongRegnCd}

    AND lDongSignguCd = #{lDongSignguCd}

SELECT * FROM (
    SELECT 
        d.*,
        ROWNUM AS rn
    FROM (
        SELECT * FROM destination ORDER BY contentid
    ) d
    WHERE ROWNUM <= #{endIndex}
)
WHERE rn >= #{startIndex}
